<script setup lang="ts">
import {computed,ref} from 'vue';import {importFormat} from '../../shared/document-formats';import Icon from '../../shared/Icon.vue';
import type {CommandState} from '../../shared/composables/useCommand';
type Item={key:string;name:string;size:number;status:string;error:string|null;uploadId:string|null;fileId:string|null;canAbort?:boolean;canRemove?:boolean};
const props=defineProps<{items:readonly Item[];ready:boolean;blocked:boolean;error:string|null;importState:CommandState;importBusy:boolean;taskId:string|null;locked?:boolean}>();
const emit=defineEmits<{add:[files:File[]];retry:[key:string,file:File];discover:[key:string];open:[];submit:[];discard:[];remove:[key:string];move:[key:string,direction:-1|1];abort:[key:string];newBatch:[]}>();
const mediaNotice=ref(''),input=ref<HTMLInputElement>();
// A temporary save/discard lock disables intake without replacing its layout.
const frozen=computed(()=>props.importState!=='EMPTY'),mutable=computed(()=>!frozen.value&&!props.locked),uploading=computed(()=>props.items.some(i=>['QUEUED','VERIFYING','INITIALIZING','ABORTING'].includes(i.status)));
const canAdd=computed(()=>props.ready&&!props.blocked&&!props.importBusy&&props.items.length<16&&mutable.value);
function addFiles(files:File[]){if(files.some(f=>!importFormat(f.name))){mediaNotice.value='所选文件格式尚未由当前解析服务支持；当前可导入 TXT、DOC、DOCX、PDF、PPTX、MP3、WAV、M4A、MP4、MOV、MKV、WEBM。';return;}mediaNotice.value='';if(files.length)emit('add',files);}
function selected(event:Event,key?:string){const field=event.target as HTMLInputElement,files=[...(field.files??[])];if(key&&files[0])emit('retry',key,files[0]);else addFiles(files);field.value='';}
function choose(){if(canAdd.value)input.value?.click();}
const stages:Record<string,string>={QUEUED:'上传中',VERIFYING:'校验中',INITIALIZING:'上传中',NEEDS_FILE:'请选择原文件以恢复',UNRESOLVED:'结果待确认',OBSERVED_COMPLETED:'可用',COMPLETION_ACKNOWLEDGED:'可用',ABORTED:'已终止',ABORTING:'正在终止',FAILED:'上传失败'};
function format(name:string){return name.match(/\.([a-z0-9]+)$/i)?.[1]?.toUpperCase()||'文件';}
</script>
<template><section class="aci-import-section" aria-labelledby="upload-heading"><div class="aci-section-title"><h3 id="upload-heading">会议主文件</h3><span class="small muted">支持多段录音及多文件添加</span></div>
 <div v-if="items.length>1&&!frozen" class="aci-main-sort-guide small muted" role="note">通过上移、下移调整主文件顺序，系统将按此顺序处理会议内容。</div>
 <div data-aci-files="main"><div v-for="(item,index) in items" :key="item.fileId??item.key" class="file-item ac-file" :class="{'ac-orderable-file':items.length>1&&!frozen}"><span v-if="items.length>1&&!frozen" class="aci-main-file-number" :aria-label="'第'+(index+1)+'个文件'">{{index+1}}</span><div class="f-ico"><Icon name="mic" :size="20"/></div><div class="ac-file-main"><div class="f-name" :title="item.name">{{item.name}}</div><div class="f-meta">{{format(item.name)}} · 本地文件 · {{(item.size/1024).toFixed(1)}} KB<template v-if="!item.fileId"> · {{stages[item.status]??item.status}}</template></div><div v-if="item.error" class="ac-error small mt8" role="alert">{{item.error}}</div></div><div class="flex wrap"><template v-if="items.length>1&&!frozen"><button type="button" class="btn sm aci-main-sort-button" :aria-label="'上移'+item.name" title="上移" :disabled="!mutable||index===0||uploading||blocked" @click="emit('move',item.key,-1)"><svg width="13" height="13" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m5 12 5-5 5 5"/></svg></button><button type="button" class="btn sm aci-main-sort-button" :aria-label="'下移'+item.name" title="下移" :disabled="!mutable||index===items.length-1||uploading||blocked" @click="emit('move',item.key,1)"><svg width="13" height="13" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m5 8 5 5 5-5"/></svg></button></template><button type="button" class="btn sm ghost" :disabled="!mutable||blocked||!item.canRemove" :aria-label="'移除'+item.name" @click="emit('remove',item.key)">移除</button></div>
  </div></div>
 <div v-if="!frozen" class="upload-zone aci-main-drop" role="button" tabindex="0" aria-label="添加会议主文件" :aria-disabled="!canAdd" @click="choose" @keydown.enter.prevent="choose" @keydown.space.prevent="choose" @dragover.prevent @drop.prevent="event=>{if(canAdd)addFiles([...(event.dataTransfer?.files??[])]);}"><Icon name="file" :size="20"/><strong>选择或拖入会议录音、视频或转写文件</strong><span>音频：MP3 / WAV / M4A / AAC / FLAC / OGG / WEBM</span><span>视频：MP4 / MOV / M4V / AVI / MKV　文本：TXT / DOCX / SRT / VTT</span><span class="small muted">可多次添加；正式格式、大小及数量限制后续补充。</span></div><div v-else class="hint">本次导入文件清单已冻结，恢复时保留原文件及顺序。</div>
 <input ref="input" hidden type="file" aria-label="选择会议文件" aria-describedby="import-service-limits" accept=".txt,.doc,.docx,.pdf,.pptx,.mp3,.wav,.m4a,.mp4,.mov,.mkv,.webm,.aac,.flac,.ogg,.m4v,.avi,.srt,.vtt,text/plain,audio/*,video/*" multiple :disabled="!canAdd" @change="selected($event)"/><span id="import-service-limits" class="sr-only">当前服务最多16个文件，每个不超过32 MiB；已接入TXT、DOC、DOCX、PDF、PPTX、AAC、FLAC、OGG、M4V、AVI、SRT、VTT及现有音视频解析。</span>
 <div v-if="error||mediaNotice" class="aci-import-error ac-error" role="alert">{{error||mediaNotice}}</div><div v-if="blocked" class="ac-error small mt8" role="alert">上传恢复记录暂不可用，请重新检查后操作。</div>
 <div v-if="importState==='ACKNOWLEDGED'" class="small muted mt8" role="status">导入任务已受理（{{taskId}}），不表示转写已完成。请在任务列表查看实际处理进度。<button type="button" class="btn sm" :disabled="importBusy||blocked" @click="emit('newBatch')">开始新一批导入</button></div>
</section></template>
